/* TILES LOG - a p0pc0rn app skeleton: a grid of tiles, one per number the person keeps track of (miles run, hours slept, rainfall,
   glasses of water, plants watered, pages read). Tap a tile to log a value; each tile shows its latest value, today's total, a 14-entry
   sparkline and an optional goal. Every number comes from the person: the slots only name the tiles.
   Slots come from window.SLOTS; every slot has a default, so the app also runs with no slots at all. */

// ===== SLOTS =====
const SL = window.SLOTS || {};
const TITLE = String(SL.title || 'My Log').slice(0, 22);
const ACCENT = /^#[0-9a-fA-F]{6}$/.test(SL.accent || '') ? SL.accent : '#30b0c7';
const okIcon = (n, d) => (typeof n === 'string' && (!K.ICONS || K.ICONS.includes(n)) ? n : d);
const MODES = ['sum', 'last'];
const TILES = (Array.isArray(SL.tiles) && SL.tiles.length ? SL.tiles : [{ label: 'Steps', unit: 'steps', icon: 'trend', step: 1000, mode: 'sum' }, { label: 'Water', unit: 'glasses', icon: 'drop', step: 1, mode: 'sum' }])
  .slice(0, 8).map((t, i) => ({ id: 't' + i, label: String(t.label || 'Tile ' + (i + 1)).slice(0, 18), unit: String(t.unit || '').slice(0, 12), icon: okIcon(t.icon, 'chart'),
    step: Math.max(0.1, Math.min(10000, +t.step || 1)), mode: MODES.includes(t.mode) ? t.mode : 'sum', goal: +t.goal > 0 ? +t.goal : 0, color: /^#[0-9a-fA-F]{6}$/.test(t.color || '') ? t.color : null }));
const NOTE = String(SL.note || '').slice(0, 120);

// ===== STATE (saved): entries per tile, newest last =====
const KEY = 'tiles.v1';
let log = {};
const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
let ui = { sheet: false, tile: null, value: 0, contentH: 800 };

function setup() {
  K.setup({ mode: 'light', accent: ACCENT });
  log = K.load(KEY, {}) || {};
  for (const t of TILES) if (!Array.isArray(log[t.id])) log[t.id] = [];
  K.scene('main', drawMain);
}
function draw() { K.render(); }
function saveState() { K.save(KEY, log); }   // 3.9: was named save, which p5 takes for its own when the app starts

const fmt = (v) => (Math.abs(v) >= 1000 ? K.fmt.compact(v) : String(Math.round(v * 10) / 10));
function today(t) { const d = dayKey(Date.now()); return log[t.id].filter((e) => dayKey(e.t) === d).reduce((s, e) => s + e.v, 0); }
function shown(t) { const L = log[t.id]; return t.mode === 'sum' ? today(t) : L.length ? L[L.length - 1].v : 0; }

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.lighten(ACCENT, 0.86) });
  const sub = NOTE || K.fmt.date(Date.now());
  const top = K.navBar.top(sub) + 8, clipY = K.navBar.bottom(), x = K.S.l, w = K.W - 2 * K.S.l;
  const off = K.scroll('main', 0, clipY, K.W, K.H - clipY, ui.contentH);
  K.clip(0, clipY, K.W, K.H - clipY, () => { ui.contentH = grid(x, top - off, w) + off - top + 40; });
  K.navBar(TITLE, off, { sub });
  ui.sheet = K.sheet('log', ui.sheet, 330, drawSheet);
}

function grid(x, y, w) {
  const y0 = y, cw = (w - K.S.m) / 2, ch = 150;
  TILES.forEach((t, i) => {
    const cx = x + (i % 2) * (cw + K.S.m), cy = y + Math.floor(i / 2) * (ch + K.S.m), col = t.color || ACCENT, v = shown(t);
    K.fade(K.stagger(i), () => {
      K.card(cx, cy, cw, ch, { r: 20 });
      K.circle(cx + 26, cy + 26, 14, { fill: K.alpha(col, 0.16) }); K.icon(t.icon, cx + 26, cy + 26, 15, col);
      K.text(t.label.toUpperCase(), cx + 48, cy + 31, 'label', K.C.text2, { maxW: cw - 56 });
      K.num(fmt(K.count('v' + t.id, v, 500)), cx + 16, cy + 82, 'title', K.C.text);
      K.text(t.unit + (t.mode === 'sum' ? ' today' : ''), cx + 16, cy + 102, 'footnote', K.C.text3, { maxW: cw - 32 });
      const vals = log[t.id].slice(-14).map((e) => e.v);
      if (t.goal && t.mode === 'sum') K.progressBar(cx + 16, cy + 124, cw - 32, 6, Math.min(1, v / t.goal), { color: col });
      else if (vals.length > 1) K.spark(vals, cx + 16, cy + 112, cw - 32, 24, { color: col, fill: true });
      K.registerControl('tile:' + t.label, cx, cy, cw, ch);
      if (K.tapIn(cx, cy, cw, ch)) { ui.tile = t; ui.value = t.mode === 'sum' ? t.step : shown(t) || t.step; ui.sheet = true; K.sfx('tap'); }
    });
  });
  y += Math.ceil(TILES.length / 2) * (ch + K.S.m) + 8;
  K.text('RECENT', x, y + 14, 'label', K.C.text2); y += 24;
  const recent = TILES.flatMap((t) => log[t.id].slice(-6).map((e) => ({ t, e }))).sort((a, b) => b.e.t - a.e.t).slice(0, 8);
  if (!recent.length) y += K.empty(K.W / 2, y + 8, 'plusCircle', 'Nothing logged yet', 'Tap a tile to log your first number.', { w }) + 12;
  else {
    K.card(x, y, w, recent.length * 50, { r: 16 });
    recent.forEach((r, i) => {
      const ry = y + i * 50; if (i) K.line(x + 16, ry, x + w - 16, ry, K.C.line, 1);
      K.icon(r.t.icon, x + 26, ry + 25, 16, r.t.color || ACCENT);
      K.text(r.t.label, x + 48, ry + 30, 'body', K.C.text, { maxW: w * 0.45 });
      K.text(fmt(r.e.v) + ' ' + r.t.unit + ' · ' + K.fmt.ago(r.e.t), x + w - 16, ry + 30, 'footnote', K.C.text2, { align: 'right' });
    });
    y += recent.length * 50 + 8;
  }
  return y - y0;
}

function drawSheet(x, y, w, h, close) {
  const t = ui.tile; if (!t) return false;
  K.text(t.label, x + 20, y + 40, 'title2', K.C.text);
  K.text(t.mode === 'sum' ? 'Add to today' : 'New value', x + 20, y + 64, 'subhead', K.C.text2);
  K.num(fmt(ui.value), x + w / 2, y + 128, 'display', K.C.text, { align: 'center' });
  K.text(t.unit, x + w / 2, y + 152, 'subhead', K.C.text3, { align: 'center' });
  ui.value = Math.max(0, K.stepper('val', x + w / 2 - 47, y + 172, ui.value, { min: 0, max: 1e6, step: t.step }));
  if (K.button('logit', x + 20, y + 230, w - 40, 52, 'Log ' + fmt(ui.value) + ' ' + t.unit, { style: 'primary', icon: 'check', disabled: !(ui.value > 0) })) {
    log[t.id].push({ t: Date.now(), v: ui.value }); log[t.id] = log[t.id].slice(-400); saveState();
    K.sfx('success'); K.toast('Logged', { tone: 'good', icon: t.icon, ms: 1200 }); close();
  }
  if (log[t.id].length && K.button('undo', x + 20, y + 290, w - 40, 36, 'Undo the last entry', { style: 'ghost', icon: 'undo' })) { log[t.id].pop(); saveState(); K.toast('Removed'); close(); }
}
